#Requires -Version 5.1

<#
.SYNOPSIS
    Lists the Azure VM sizes that can host AVD session hosts in a region, and whether your quota allows them. Read-only.

.DESCRIPTION
    Checks which VM sizes in one Azure region are suitable for Azure Virtual Desktop
    session hosts: approved AVD-capable series, minimum vCPU and memory, workload
    category, SKU restrictions on the subscription, and remaining vCPU quota. It can
    add pay-as-you-go prices and limit the list to sizes with Accelerated Networking.
    It changes nothing in Azure.

    The script runs in English, Spanish or Portuguese. Without -Language it asks.

    Every run signs in afresh. Before signing in it clears the Azure PowerShell sign-in
    saved on this computer (Clear-AzContext), so other Azure PowerShell sessions will
    need to sign in again afterwards. Interactive runs offer browser, device code and
    other sign-in methods; -NonInteractive uses browser sign-in.

    Missing Az modules are staged in a temporary folder for the run and removed
    afterwards. Unless -NoExport is given, an Excel report is written beside the script.

.PARAMETER Language
    English, Spanish or Portuguese (en-US, es-VE and pt-BR are also accepted).
    Without it the script asks, or uses English with -NonInteractive.

.PARAMETER SubscriptionId
    The subscription to check. Without it the script lists your subscriptions to choose from.
    With -NonInteractive, give it: otherwise the signed-in account's default subscription is used.

.PARAMETER TenantId
    The Microsoft Entra tenant to sign in to. Without it the script lists your tenants to choose from.
    Required with -NonInteractive.

.PARAMETER Location
    The Azure region to check, by short name (for example eastus2, westeurope).
    Without it the script asks, also with -NonInteractive, so give it for unattended runs.

.PARAMETER MinCores
    The fewest vCPUs a size may have to be listed. 1 to 128; default 1.

.PARAMETER MinMemoryGB
    The least memory, in GB, a size may have to be listed. 1 to 512; default 4.

.PARAMETER WorkloadType
    Limits the list to one workload category: Light, Medium, Heavy, Graphics (GPU sizes), or All (default).

.PARAMETER IncludePricing
    Adds pay-as-you-go prices from the Azure Retail Prices API.

.PARAMETER IncludeOnlyAccelerated
    Lists only sizes that support Accelerated Networking.

.PARAMETER DeploymentReadyOnly
    $true (default) lists only sizes that the subscription may use and that fit the
    remaining quota. $false lists every suitable size, marked ready or not, with any SKU restriction.

.PARAMETER ForceReauth
    Accepted for compatibility. Every run already signs in afresh.

.PARAMETER NonInteractive
    Runs without menus or prompts, for automation. Give -TenantId, -SubscriptionId and -Location.

.PARAMETER PassThru
    Also returns the analysed VM sizes as objects, for use in a pipeline.

.PARAMETER NoExport
    Does not write the Excel report.

.PARAMETER SkipModuleValidation
    Skips the check for the required Az modules. For a calling script that has already done it.

.EXAMPLE
    .\01_AVD_Validate_VMSizeAndQuota.ps1

    Asks for the language, sign-in, subscription and region, then lists the deployable sizes.

.EXAMPLE
    .\01_AVD_Validate_VMSizeAndQuota.ps1 -Language English -TenantId "YOUR-TENANT-ID" -SubscriptionId "YOUR-SUBSCRIPTION-ID" -Location eastus2 -MinCores 4 -MinMemoryGB 16 -NonInteractive

    Unattended run for sizes with at least 4 vCPUs and 16 GB in East US 2.

.EXAMPLE
    .\01_AVD_Validate_VMSizeAndQuota.ps1 -Location westeurope -WorkloadType Graphics -IncludePricing -DeploymentReadyOnly $false

    Every GPU size in West Europe with prices, including those the subscription cannot deploy yet.
#>
[CmdletBinding(SupportsShouldProcess = $false)]
param(
    [ValidateSet('English', 'Spanish', 'Portuguese', 'en-US', 'es-VE', 'pt-BR')]
    [string]$Language,
    [Parameter(Mandatory=$false, HelpMessage="Azure Subscription ID")]
    [string]$SubscriptionId,
    [Parameter(Mandatory=$false, HelpMessage="Azure AD Tenant ID")]
    [string]$TenantId,
    [Parameter(Mandatory=$false, HelpMessage="Azure region for VM size discovery")]
    [string]$Location,
    [ValidateRange(1, 128)]
    [int]$MinCores = 1,
    [ValidateRange(1, 512)]
    [int]$MinMemoryGB = 4,
    [ValidateSet("Light", "Medium", "Heavy", "Graphics", "All")]
    [string]$WorkloadType = "All",
    [switch]$IncludePricing,
    [switch]$IncludeOnlyAccelerated,
    [bool]$DeploymentReadyOnly = $true,
    [switch]$ForceReauth,
    [switch]$NonInteractive,
    [switch]$PassThru,
    [switch]$NoExport,
    [switch]$SkipModuleValidation
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# Embedded source hashes: English=4B13E1087C8782614699A1DAFE8592E6AC2E196EE73A3192A1F09473074C88F1; Spanish=22989347B4E372D17350D4F35DAD03C2C7EF051C3FCD1E3A1C8E0B136E65E88F; Portuguese=D1261450DFFD789570FA62307F8BD34029BB1B770AF85B90C04E8FDCC989FA3B
$embeddedPayloads = @{
    English = ''
    Spanish = ''
    Portuguese = ''
}

function Expand-EmbeddedScript {
    param([Parameter(Mandatory = $true)][string]$Payload)
    $compressed = [Convert]::FromBase64String($Payload)
    $inputStream = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { $reader.ReadToEnd() } finally { $reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose() }
}

if (-not $Language) {
    if ($NonInteractive) {
        $Language = 'English'
    } else {
        do {
            Write-Host ''
            Write-Host 'Select language / Seleccione el idioma / Selecione o idioma' -ForegroundColor Cyan
            Write-Host '  1. English'
            Write-Host '  2. Español'
            Write-Host '  3. Português'
            $languageChoice = Read-Host 'Choice / Opción / Opção [1]'
            if ([string]::IsNullOrWhiteSpace($languageChoice)) { $languageChoice = '1' }
        } until ($languageChoice -in @('1', '2', '3'))
        $Language = @{'1' = 'English'; '2' = 'Spanish'; '3' = 'Portuguese'}[$languageChoice]
    }
}
$normalizedLanguage = if ($Language -in @('Spanish', 'es-VE')) { 'Spanish' } elseif ($Language -in @('Portuguese', 'pt-BR')) { 'Portuguese' } else { 'English' }

$forwardParameters = @{}
foreach ($parameterName in $PSBoundParameters.Keys) {
    if ($parameterName -ne 'Language') { $forwardParameters[$parameterName] = $PSBoundParameters[$parameterName] }
}
$forwardParameters.ForceReauth = $true
if (-not $NoExport) {
    $forwardParameters.ExportExcelPath = Join-Path $PSScriptRoot ("01_AVD_Validate_VMSizeAndQuota_Launcher_{0}.xlsx" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
}

# The engine runs in this PowerShell session, so the script behaves the same in Windows
# PowerShell 5.1, PowerShell 7 and PowerShell ISE. For the run it works from the script's
# folder, with its own temporary folder; the folder, TEMP and the module path are restored when it finishes, whether it passes or fails.
# Modules an earlier run loaded stay locked until its window closes, so that run could not
# delete its temporary folder. Delete those now; a rename fails while a folder is still in use.
Get-ChildItem -Path ([IO.Path]::GetTempPath()) -Directory -Filter 'AVD01_Temp_*' -ErrorAction SilentlyContinue | ForEach-Object {
    $staleName = 'AVD01_Stale_{0}' -f [guid]::NewGuid().ToString('N')
    try { Rename-Item -LiteralPath $_.FullName -NewName $staleName -ErrorAction Stop } catch { return }
    Remove-Item -LiteralPath (Join-Path ([IO.Path]::GetTempPath()) $staleName) -Recurse -Force -ErrorAction SilentlyContinue
}
Get-ChildItem -Path ([IO.Path]::GetTempPath()) -Directory -Filter 'AVD01_Stale_*' -ErrorAction SilentlyContinue |
    ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
$engineTempPath = Join-Path ([IO.Path]::GetTempPath()) ("AVD01_Temp_{0}" -f [guid]::NewGuid().ToString('N'))
$previousEnvironment = @{
    AVD_REPORT_SCRIPT_NAME = $env:AVD_REPORT_SCRIPT_NAME
    PSModulePath = $env:PSModulePath
    TEMP = $env:TEMP
    TMP = $env:TMP
}
$previousLocation = Get-Location
try {
    New-Item -ItemType Directory -Path $engineTempPath -ErrorAction Stop | Out-Null
    $env:AVD_REPORT_SCRIPT_NAME = '01_AVD_Validate_VMSizeAndQuota_Launcher'
    $env:TEMP = $engineTempPath
    $env:TMP = $engineTempPath
    Set-Location -LiteralPath $PSScriptRoot
    $engine = [scriptblock]::Create((Expand-EmbeddedScript -Payload $embeddedPayloads[$normalizedLanguage]))
    $global:LASTEXITCODE = 0
    & $engine @forwardParameters
} finally {
    Set-Location -LiteralPath $previousLocation.Path
    foreach ($name in $previousEnvironment.Keys) {
        $value = $previousEnvironment[$name]
        if ($null -eq $value) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue } else { Set-Item "Env:$name" $value }
    }
    # Modules the engine loaded from here stay locked until PowerShell closes; what can be removed is.
    Remove-Item -LiteralPath $engineTempPath -Recurse -Force -ErrorAction SilentlyContinue
}
